import json, pathlib
for p in [pathlib.Path('backend/tests/evidence/backend-acceptance-results.json'), pathlib.Path('.domainry/development/acceptance-evidence/backend-acceptance-run.json')]:
 print('\\nFILE',p,'exists',p.exists(),'size',p.stat().st_size if p.exists() else None)
 if p.exists():
  try:
   d=json.loads(p.read_text())
   print('type',type(d).__name__)
   if isinstance(d,dict):
    print('keys',list(d)[:30])
    for k in ['ok','status','summary','counts','passed','failed','skipped','denominator_sha256','results_sha256','receipt_sha256']:
     if k in d: print(k,d[k])
    rows=d.get('results') or d.get('cases') or d.get('rows')
    if isinstance(rows,list):
     print('rows',len(rows))
     fails=[]
