		Variables: []capabilities.ApproveLeadConversionNotificationVariable{{Key: "company_name", StringValue: &company}},
	})
	if err != nil {
		return out, err
	}
	_ = updatedApproval
	out.CustomerID = string(customer.ID)
	return out, nil
}
