func TestScanStaleLeadsCreatesDailyReceiptAndInboxIntent(t *testing.T) {
	owner := "east_rep_user"
	changed := time.Date(2026, 8, 10, 9, 0, 0, 0, time.UTC)
	leads := &fakeLeadStore{leads: []schema.Lead{{ID: "lead-stale", UpdatedAt: "lead-v1", CompanyName: "逾期公司", OwnerUser: &owner, Status: schema.LeadStatus("contacted"), StatusChangedAt: &changed}}}
	reminders := &fakeReminderStore{exists: []bool{false}}
	runs := &fakeFollowupScanRunStore{}
	notifications := &scanNotifications{}
	out, err := ScanStaleLeads(t.Context(), capabilities.ScanStaleLeadsCapabilities{Execution: objectExecution{principal: testPrincipal("sales_director_user", "sales_director")}, Lead: leads, ReminderReceipt: reminders, FollowupScanRun: runs, Notifications: notifications}, capabilities.ScanStaleLeadsInput{RunDate: time.Date(2026, 8, 25, 0, 0, 0, 0, time.UTC), ScheduledAt: time.Date(2026, 8, 25, 1, 0, 0, 0, time.UTC)})
	if err != nil {
		t.Fatal(err)
	}
	if out.ReminderCount != 1 || leads.listCalls != 1 || reminders.createBatchCalls != 1 || notifications.batchCalls != 1 || runs.createCalls != 1 {
		t.Fatalf("out=%+v effects=%d/%d/%d/%d", out, leads.listCalls, reminders.createBatchCalls, notifications.batchCalls, runs.createCalls)
	}
}
