// RejectLeadConversion implements the project-owned conversion_approval.reject_lead_conversion Handler.
func RejectLeadConversion(ctx context.Context, caps capabilities.RejectLeadConversionCapabilities, input capabilities.RejectLeadConversionInput) (capabilities.RejectLeadConversionOutput, error) {
	var out capabilities.RejectLeadConversionOutput
	reason := strings.TrimSpace(input.Reason)
	if caps.Execution == nil || caps.ConversionApproval == nil || caps.Lead == nil || caps.Notifications == nil || input.RequestID == "" || input.ApprovalID == "" || reason == "" {
		return out, &capabilities.BusinessError{Code: "conversion.reject.invalid_input"}
	}
	principal := caps.Execution.Principal()
	approval, err := caps.ConversionApproval.GetForUpdate(ctx, input.ApprovalID)
	if err != nil {
		return out, err
	}
	if approval.Status != schema.ConversionApprovalStatus("pending") || approval.RequesterUser == nil {
		return out, &capabilities.BusinessError{Code: "conversion.approval.not_pending"}
	}
	lead, err := caps.Lead.Get(ctx, approval.LeadID.ID())
	if err != nil {
		return out, err
	}
	if lead.Status != schema.LeadStatus("qualified") {
		return out, &capabilities.BusinessError{Code: "lead.conversion.qualified_required"}
	}
	now := time.Now().UTC()
	updated, err := caps.ConversionApproval.ConditionalUpdate(ctx, data.NewConversionApprovalUpdate(approval.ID).
		SetStatus(schema.ConversionApprovalStatus("rejected")).SetRejectionReason(reason).
		SetDecidedBy(principal.UserID).SetDecisionAt(now).
		RequireStatusEqual(schema.ConversionApprovalStatus("pending"), "conversion.approval.state_changed").WithExpectedUpdatedAt(approval.UpdatedAt))
	if err != nil {
		return out, err
	}
	company := lead.CompanyName
	_, err = caps.Notifications.Dispatch(ctx, capabilities.RejectLeadConversionNotificationIntent{
		EventType: "conversion.rejected", SourceEventID: "conversion.rejected:" + string(approval.ID),
		RecipientUserIDs: []string{*approval.RequesterUser}, Surface: "business_workspace",
		SubjectObjectKey: "lead", SubjectRecordID: string(lead.ID), SubjectVersion: lead.UpdatedAt,
		DedupeKey: "conversion.rejected:" + string(approval.ID), OccurredAt: now,
		Variables: []capabilities.RejectLeadConversionNotificationVariable{{Key: "company_name", StringValue: &company}, {Key: "reason", StringValue: &reason}},
	})
	if err != nil {
		return out, err
	}
	_ = updated
	out.Status = schema.ConversionDecisionContextRejectLeadConversionStatusRejected
	return out, nil
}
