	notifications := &approveNotifications{}
	out, err := ApproveLeadConversion(t.Context(), capabilities.ApproveLeadConversionCapabilities{Execution: objectExecution{principal: testPrincipal("sales_director_user", "sales_director")}, ConversionApproval: approvals, Lead: leads, Customer: customers, Notifications: notifications}, capabilities.ApproveLeadConversionInput{RequestID: "approve-1", ApprovalID: "approval-1"})
