// ReportRecordAdapter is the Report-owned anti-corruption layer over Record use cases.
type ReportRecordAdapter struct {
	application *recordapplication.RecordApplicationService
	repository  recordrepository.RecordRepository
	schemaMap   func() map[string]definitionmodel.ObjectSchema
}

func NewReportRecordAdapter(application *recordapplication.RecordApplicationService, repository recordrepository.RecordRepository, schemaMaps ...func() map[string]definitionmodel.ObjectSchema) *ReportRecordAdapter {
	var schemaMap func() map[string]definitionmodel.ObjectSchema
	if len(schemaMaps) > 0 {
		schemaMap = schemaMaps[0]
	}
	return &ReportRecordAdapter{application: application, repository: repository, schemaMap: schemaMap}
}

func (a *ReportRecordAdapter) ReportObjectForAction(_ context.Context, principal identitymodel.Principal, objectKey, action string) (definitionmodel.ObjectSchema, error) {
	return a.application.ObjectForAction(principal, objectKey, action)
}

func (a *ReportRecordAdapter) NormalizeReportListQuery(_ context.Context, object definitionmodel.ObjectSchema, query recordmodel.RecordListQuery, principal identitymodel.Principal) recordmodel.RecordListQuery {
	return a.application.NormalizeListQuery(object, query, principal)
}

func (a *ReportRecordAdapter) CanAccessReportRecord(_ context.Context, principal identitymodel.Principal, object definitionmodel.ObjectSchema, record recordmodel.Record) bool {
	return a.application.CanAccessRecord(principal, object, record)
}

func (a *ReportRecordAdapter) ProjectReportRecordFields(ctx context.Context, principal identitymodel.Principal, object definitionmodel.ObjectSchema, records []recordmodel.Record) ([]recordmodel.Record, error) {
	return a.application.ProjectRecordFields(ctx, principal, object, records, "report")
}

func (a *ReportRecordAdapter) CanPushdownReportDataset(_ context.Context, principal identitymodel.Principal, objects []definitionmodel.ObjectSchema) bool {
	for _, object := range objects {
		for _, field := range object.Fields {
			if !recordpolicy.RecordCanReadField(principal.Role, object.Key, field.Key) || recordpolicy.RecordFieldReadMasked(principal.Role, object.Key, field.Key) {
				return false
			}
		}
		for _, permission := range principal.Role.FieldPermissions {
			if permission.ObjectKey == object.Key && len(permission.Policies) > 0 {
				return false
			}
		}
	}
	return true
}

func (a *ReportRecordAdapter) AuthorizeReportExportField(_ context.Context, principal identitymodel.Principal, objectKey, fieldKey string) (bool, error) {
	object, err := a.application.ObjectForAction(principal, objectKey, "export")
	if err != nil {
		return false, err
	}
	if fieldKey == "id" || fieldKey == "created_at" || fieldKey == "updated_at" {
		if !recordpolicy.RecordCanExportField(principal.Role, object.Key, fieldKey) {
			return false, &apperror.AppError{Kind: apperror.KindForbidden, Code: "backend.report.export_field_denied"}
		}
		return recordpolicy.RecordFieldExportMasked(principal.Role, object.Key, fieldKey), nil
	}
	for _, field := range object.Fields {
		if field.Key != fieldKey || field.DisabledAt != "" {
			continue
		}
		if !recordpolicy.RecordCanExportObjectField(principal.Role, object, field) {
			return false, &apperror.AppError{Kind: apperror.KindForbidden, Code: "backend.report.export_field_denied"}
		}
		return recordpolicy.RecordFieldExportMasked(principal.Role, object.Key, field.Key), nil
	}
	return false, &apperror.AppError{Kind: apperror.KindBadRequest, Code: "backend.report.export_field_not_found"}
}

func (a *ReportRecordAdapter) AuthorizeReportObjectSQLField(_ context.Context, principal identitymodel.Principal, object definitionmodel.ObjectSchema, fieldKey string) error {
	fieldKey = strings.TrimSpace(fieldKey)
	if _, err := a.application.ObjectForAction(principal, object.Key, "read"); err != nil {
		return err
	}
	if fieldKey != "id" && fieldKey != "created_at" && fieldKey != "updated_at" {
		found := false
		for _, field := range object.Fields {
			if field.Key == fieldKey && strings.TrimSpace(field.DisabledAt) == "" {
				found = true
				if !recordpolicy.RecordCanReadObjectField(principal.Role, object, field) {
					return &apperror.AppError{Kind: apperror.KindForbidden, Code: "backend.report.object_sql_field_denied"}
				}
				break
			}
		}
		if !found {
			return &apperror.AppError{Kind: apperror.KindBadRequest, Code: "backend.report.object_sql_field_not_found"}
		}
	} else if !recordpolicy.RecordCanReadField(principal.Role, object.Key, fieldKey) {
		return &apperror.AppError{Kind: apperror.KindForbidden, Code: "backend.report.object_sql_field_denied"}
