func RecordCanReadField(role identitymodel.RoleSchema, objectKey, fieldKey string) bool {
	if identitycontract.IdentityRoleGuardrailDeniesField(role, objectKey, fieldKey, "read") {
		return false
	}
	if identitycontract.IdentityRoleAllows(role, "workspace", "admin") {
		return true
	}
	found := false
	for _, permission := range role.FieldPermissions {
		if permission.ObjectKey == objectKey && permission.FieldKey == fieldKey {
			found = true
			if permission.Read {
				return true
			}
		}
	}
	return !found
}

func RecordCanWriteField(role identitymodel.RoleSchema, objectKey, fieldKey string) bool {
	if identitycontract.IdentityRoleGuardrailDeniesField(role, objectKey, fieldKey, "update") {
		return false
	}
	if identitycontract.IdentityRoleAllows(role, "workspace", "admin") {
		return true
	}
	found := false
	for _, permission := range role.FieldPermissions {
		if permission.ObjectKey == objectKey && permission.FieldKey == fieldKey {
			found = true
			if permission.Write {
				return true
			}
		}
	}
	return !found
}

func RecordCanExportField(role identitymodel.RoleSchema, objectKey, fieldKey string) bool {
	if identitycontract.IdentityRoleGuardrailDeniesField(role, objectKey, fieldKey, "export") {
		return false
	}
	if identitycontract.IdentityRoleAllows(role, "workspace", "admin") {
		return true
	}
	if len(role.ExportRules) > 0 {
		allowedByRule := false
		for _, rule := range role.ExportRules {
			if rule.ObjectKey != objectKey {
				continue
			}
			if len(rule.Fields) == 0 || recordContractContainsString(rule.Fields, fieldKey) {
				allowedByRule = true
				break
			}
		}
		if !allowedByRule {
			return false
		}
	}
	for _, permission := range role.FieldPermissions {
		if permission.ObjectKey == objectKey && permission.FieldKey == fieldKey {
			if permission.Export {
				return true
			}
		}
	}
	for _, permission := range role.FieldPermissions {
		if permission.ObjectKey == objectKey && permission.FieldKey == fieldKey {
			return false
		}
	}
	return true
}

func recordContractContainsString(items []string, target string) bool {
	for _, item := range items {
		if item == target {
			return true
		}
	}
	return false
}

