func ProgressLeadState(ctx context.Context, caps capabilities.ProgressLeadStateCapabilities, input capabilities.ProgressLeadStateInput) (capabilities.ProgressLeadStateOutput, error) {
	var out capabilities.ProgressLeadStateOutput
	if caps.Execution == nil || caps.Lead == nil || input.RequestID == "" || input.LeadID == "" {
		return out, &capabilities.BusinessError{Code: "lead.transition.invalid_input"}
	}
	principal := caps.Execution.Principal()
	lead, err := caps.Lead.GetForUpdate(ctx, input.LeadID)
	if err != nil {
		return out, err
	}
	if !principal.Known || lead.OwnerUser == nil || *lead.OwnerUser != principal.UserID {
		return out, &capabilities.BusinessError{Code: "lead.owner_required"}
	}
	target := schema.LeadStatus(input.TargetStatus)
	allowed := (lead.Status == schema.LeadStatus("new") && target == schema.LeadStatus("contacted")) ||
		(lead.Status == schema.LeadStatus("contacted") && target == schema.LeadStatus("qualified")) ||
		(lead.Status == schema.LeadStatus("qualified") && target == schema.LeadStatus("lost"))
	if !allowed {
		return out, &capabilities.BusinessError{Code: "lead.invalid_transition"}
	}
	mutation := data.NewLeadUpdate(lead.ID).
		SetStatus(target).
		SetStatusChangedAt(time.Now().UTC()).
		RequireStatusEqual(lead.Status, "lead.state_changed").
		WithExpectedUpdatedAt(lead.UpdatedAt)
	_, err = caps.Lead.ConditionalUpdate(ctx, mutation)
	if err != nil {
		return out, err
	}
	out.Status = schema.LeadProgressLeadStateStatus(target)
	return out, nil
}
