// RequestLeadConversion implements the project-owned lead.request_lead_conversion Handler.
func RequestLeadConversion(ctx context.Context, caps capabilities.RequestLeadConversionCapabilities, input capabilities.RequestLeadConversionInput) (capabilities.RequestLeadConversionOutput, error) {
	var out capabilities.RequestLeadConversionOutput
	if caps.Execution == nil || caps.Lead == nil || caps.Customer == nil || caps.ConversionApproval == nil || strings.TrimSpace(input.RequestID) == "" || input.LeadID == "" {
		return out, &capabilities.BusinessError{Code: "lead.conversion.invalid_input"}
	}
	principal := caps.Execution.Principal()
	lead, err := caps.Lead.GetForUpdate(ctx, input.LeadID)
	if err != nil {
		return out, err
	}
	if !principal.Known || lead.OwnerUser == nil || *lead.OwnerUser != principal.UserID {
		return out, &capabilities.BusinessError{Code: "lead.owner_required"}
	}
	if lead.Status != schema.LeadStatus("qualified") {
		return out, &capabilities.BusinessError{Code: "lead.conversion.qualified_required"}
	}
	leadRef := schema.NewCustomerSourceLeadIDReference(lead.ID)
	customerExists, err := caps.Customer.Exists(ctx, data.NewCustomerQuery().WhereSourceLeadIDEqual(leadRef).Page(1, 1))
	if err != nil {
		return out, err
	}
	approvalExists, err := caps.ConversionApproval.Exists(ctx, data.NewConversionApprovalQuery().WhereLeadIDEqual(schema.NewConversionApprovalLeadIDReference(lead.ID)).Page(1, 1))
	if err != nil {
		return out, err
	}
	if customerExists || approvalExists {
		return out, &capabilities.BusinessError{Code: "lead.conversion.already_requested"}
	}
	amount, ok := new(big.Rat).SetString(string(lead.ExpectedAmount))
	if !ok {
		return out, &capabilities.BusinessError{Code: "lead.amount.invalid"}
	}
	threshold := new(big.Rat).SetInt64(100000)
	if amount.Cmp(threshold) < 0 {
		customer, createErr := caps.Customer.Create(ctx, newCustomerFromLead(lead))
		if createErr != nil {
			return out, createErr
		}
		mutation := data.NewLeadUpdate(lead.ID).
			SetStatus(schema.LeadStatus("converted")).
			SetStatusChangedAt(time.Now().UTC()).
			RequireStatusEqual(schema.LeadStatus("qualified"), "lead.conversion.state_changed").
			WithExpectedUpdatedAt(lead.UpdatedAt)
		if _, err = caps.Lead.ConditionalUpdate(ctx, mutation); err != nil {
			return out, err
		}
		out.Result = schema.LeadRequestLeadConversionResult("converted")
		out.ResultID = string(customer.ID)
		return out, nil
	}
	requester := principal.UserID
	approval, err := caps.ConversionApproval.Create(ctx, schema.CreateConversionApproval{
		LeadID: schema.NewConversionApprovalLeadIDReference(lead.ID), RequesterUser: &requester,
		Status: schema.ConversionApprovalStatus("pending"), RequestKey: input.RequestID,
	})
	if err != nil {
		return out, err
	}
	out.Result = schema.LeadRequestLeadConversionResult("pending_approval")
	out.ResultID = string(approval.ID)
	return out, nil
}

func newCustomerFromLead(lead schema.Lead) schema.CreateCustomer {
	return schema.CreateCustomer{
		CompanyName: lead.CompanyName, ContactName: lead.ContactName,
		ExpectedAmount: schema.CustomerExpectedAmount(lead.ExpectedAmount),
		SourceLeadID:   schema.NewCustomerSourceLeadIDReference(lead.ID),
		Source:         schema.CustomerSource(lead.Source), OwnerUser: lead.OwnerUser,
		OwnerDepartmentID: lead.OwnerDepartmentID, OwnerDepartmentPath: lead.OwnerDepartmentPath,
	}
}

