func ScanStaleLeads(ctx context.Context, caps capabilities.ScanStaleLeadsCapabilities, input capabilities.ScanStaleLeadsInput) (capabilities.ScanStaleLeadsOutput, error) {
	var out capabilities.ScanStaleLeadsOutput
	if caps.Execution == nil || caps.Lead == nil || caps.ReminderReceipt == nil || caps.FollowupScanRun == nil || caps.Notifications == nil || input.RunDate.IsZero() || input.ScheduledAt.IsZero() {
		return out, &capabilities.BusinessError{Code: "lead.followup_scan.invalid_input"}
	}
	alreadyRun, err := caps.FollowupScanRun.Exists(ctx, data.NewFollowupScanRunQuery().WhereRunDateEqual(input.RunDate).Page(1, 1))
	if err != nil {
		return out, err
	}
	if alreadyRun {
		return out, nil
	}
	cutoff := input.ScheduledAt.Add(-7 * 24 * time.Hour)
	leads, err := caps.Lead.List(ctx, data.NewLeadQuery().
		WhereStatusEqual(schema.LeadStatus("contacted")).
		WhereStatusChangedAtLessThanOrEqual(cutoff).
		OrderByIDAscending().Page(1, 200))
	if err != nil {
		return out, err
	}
	dateKey := input.RunDate.Format("2006-01-02")
	queries := make([]data.ReminderReceiptQuery, 0, len(leads))
	eligible := make([]schema.Lead, 0, len(leads))
	keys := make([]string, 0, len(leads))
	for _, lead := range leads {
		if lead.OwnerUser == nil || lead.StatusChangedAt == nil || lead.StatusChangedAt.After(cutoff) {
			continue
		}
		key := fmt.Sprintf("%s:%s", lead.ID, dateKey)
		eligible = append(eligible, lead)
		keys = append(keys, key)
		queries = append(queries, data.NewReminderReceiptQuery().WhereDedupeKeyEqual(key).Page(1, 1))
	}
	if len(queries) == 0 {
		return finishFollowupScan(ctx, caps, input, out)
	}
	exists, err := caps.ReminderReceipt.ExistsBatch(ctx, queries)
	if err != nil {
		return out, err
	}
	creates := make([]schema.CreateReminderReceipt, 0, len(eligible))
	intents := make([]capabilities.ScanStaleLeadsNotificationIntent, 0, len(eligible))
	for index, lead := range eligible {
		if exists[index] {
			continue
		}
		owner := *lead.OwnerUser
		company := lead.CompanyName
		creates = append(creates, schema.CreateReminderReceipt{LeadID: schema.NewReminderReceiptLeadIDReference(lead.ID), ReminderDate: input.RunDate, DedupeKey: keys[index], RecipientUser: owner})
		intents = append(intents, capabilities.ScanStaleLeadsNotificationIntent{EventType: "lead.followup_due", SourceEventID: keys[index], RecipientUserIDs: []string{owner}, Surface: "business_workspace", SubjectObjectKey: "lead", SubjectRecordID: string(lead.ID), SubjectVersion: lead.UpdatedAt, DedupeKey: keys[index], OccurredAt: input.ScheduledAt, Variables: []capabilities.ScanStaleLeadsNotificationVariable{{Key: "company_name", StringValue: &company}}})
	}
	if len(creates) == 0 {
		return finishFollowupScan(ctx, caps, input, out)
	}
	created, err := caps.ReminderReceipt.CreateBatch(ctx, creates)
	if err != nil {
		return out, err
	}
	receipts, err := caps.Notifications.DispatchBatch(ctx, intents)
	if err != nil {
		return out, err
	}
	if len(created) != len(creates) || len(receipts) != len(intents) {
		return out, &capabilities.BusinessError{Code: "lead.followup_scan.incomplete_batch"}
	}
	out.ReminderCount = int64(len(created))
	return finishFollowupScan(ctx, caps, input, out)
}

func finishFollowupScan(ctx context.Context, caps capabilities.ScanStaleLeadsCapabilities, input capabilities.ScanStaleLeadsInput, out capabilities.ScanStaleLeadsOutput) (capabilities.ScanStaleLeadsOutput, error) {
	if _, err := caps.FollowupScanRun.Create(ctx, schema.CreateFollowupScanRun{RunDate: input.RunDate, ScheduledAt: input.ScheduledAt, ReminderCount: out.ReminderCount}); err != nil {
		return capabilities.ScanStaleLeadsOutput{}, err
	}
	return out, nil
}
